{"cmd":"sqlite3 data/f1.sqlite << 'EOF'
-- Check: in pit-data races, how many Race laps have a retirement for the same driver on the same lap?
SELECT COUNT(*) FROM (
    SELECT lp.race_id, lp.driver_id, lp.lap
    FROM lap_positions lp
    JOIN races_ext re ON lp.race_id = re.race_id
    JOIN retirements rt ON lp.race_id = rt.race_id AND lp.driver_id = rt.driver_id AND lp.lap = rt.lap
    WHERE lp.lap_type = 'Race' AND lp.lap >= 1 AND re.is_pit_data_available = 1
);
EOF"}

{"cmd":"sqlite3 data/f1.sqlite << 'EOF'
-- Check: in ALL races, how many Race laps have a retirement for the same driver on the same lap?
SELECT COUNT(*) FROM (
    SELECT lp.race_id, lp.driver_id, lp.lap
    FROM lap_positions lp
    JOIN retirements rt ON lp.race_id = rt.race_id AND lp.driver_id = rt.driver_id AND lp.lap = rt.lap
    WHERE lp.lap_type = 'Race' AND lp.lap >= 1
);
EOF"}

{"cmd":"sqlite3 data/f1.sqlite << 'EOF'
-- Let me check race 13 lap 1
SELECT * FROM lap_positions WHERE race_id = 13 AND lap = 1 AND lap_type = 'Race' ORDER BY position;
SELECT '---';
SELECT * FROM results WHERE race_id = 13 ORDER BY grid;
EOF"}

{"cmd":"sqlite3 data/f1.sqlite << 'EOF'
-- For race 13 lap 1: check grid, race positions, and retirements
-- Driver 17 retired on lap 1 in race 13
-- This driver was at grid position 20 (from results) and position 18 on lap 1
SELECT 'Race 13 lap 1 positions:' as info;
SELECT driver_id, position FROM lap_positions WHERE race_id = 13 AND lap = 1 AND lap_type = 'Race' ORDER BY position;
SELECT 'Race 13 grid:' as info;
SELECT driver_id, grid FROM results WHERE race_id = 13 ORDER BY grid;
SELECT 'Race 13 retirements on lap 1:' as info;
SELECT * FROM retirements WHERE race_id = 13 AND lap = 1;
EOF"}

{"cmd":"sqlite3 data/f1.sqlite << 'EOF'
-- Look at race 155 lap 1 to verify R events
SELECT 'Lap 1 positions:' as info;
SELECT driver_id, position FROM lap_positions WHERE race_id = 155 AND lap = 1 AND lap_type = 'Race' ORDER BY position;
SELECT 'Grid:' as info;
SELECT driver_id, grid FROM results WHERE race_id = 155 ORDER BY grid;
SELECT 'Retirements lap 1:' as info;
SELECT * FROM retirements WHERE race_id = 155 AND lap = 1;
EOF"}

